import { styled } from '@hexa-ui/theme';

export const StyledBrandPowerContextBanner = styled('div', {
  opacity: 1,
  transition: 'opacity 300ms ease',

  '& > div': {
    color: '#005AB5',
    background: 'linear-gradient(90deg, #D6EAFF 0%, #EAF7FF 100%)',
    border: '1px solid rgba(0, 110, 219, 0.2)',
    borderRadius: '8px',
    boxShadow: 'none',
  },

  variants: {
    closing: {
      true: {
        opacity: 0,
      },
    },
  },
});

export const StyledBrandPowerContextBannerMessage = styled('span', {
  color: '#0F4C81',
});
